package com.networkzero.session;

import com.networkzero.net.*;
import com.networkzero.room.GameState;
import java.io.IOException;
import java.util.function.Consumer;
import java.util.*;
import java.util.UUID;

/** Host authority: applies an intent once, then sends a full snapshot. */
public final class HostSession implements GameSession {
    private final GameState state;private final String name;private final GameServer server;private final IntentHandler intents=new IntentHandler();private final Consumer<IntentHandler.Result> result;private final Map<String,ArrayDeque<Long>> chatRates=new HashMap<>();private final HintManager hints=new HintManager();private final SessionRepository hintHistory=new SessionRepository();private final String sessionId=UUID.randomUUID().toString();private volatile String partner="",activity="in the room";private volatile Consumer<Object> networkListener;private volatile Consumer<Network.Intent> intentOverride;private volatile boolean clientReady;private long lastTimerSync;
    public HostSession(GameState state,String name,Consumer<IntentHandler.Result> result)throws IOException{this.state=state;this.name=name;this.result=result;server=new GameServer(name,()->this.state,new GameServer.Handler(){public void onConnected(String n){partner=n;relaySystem(n+" joined");}public void onMessage(Object m){if(m instanceof Network.Intent i)apply(i,nPartner());else if(m instanceof Network.Chat c)acceptChat(nPartner(),c.text);else if(m instanceof Network.PresenceUpdate p)activity=p.activity;else if(m instanceof Network.Ready r){clientReady=r.ready;notifyNetwork(m);}else if(m instanceof Network.RoomReady||m instanceof Network.StoryReady||m instanceof Network.GameEvent){notifyNetwork(m);}}public void onDisconnected(String n){partner="";activity="in the room";state.paused=true;state.lockOwner.clear();state.doorConfirmHost=false;state.doorConfirmClient=false;clientReady=false;relaySystem(n+" left");notifyNetwork(new Network.PartnerLeft(n));}});server.start();}
    private String nPartner(){return server.partnerName();}private void serverSafe(Object m){server.send(m);}
    private void notifyNetwork(Object m){Consumer<Object> c=networkListener;if(c!=null)c.accept(m);}
    private void apply(Network.Intent i,String player){Consumer<Network.Intent> override=intentOverride;if(override!=null&&i.type==Network.Intent.Type.UI_CLICK){override.accept(i);publish();return;}if(i.type==Network.Intent.Type.OPEN_PANEL&&!CoopRules.canOpen(state.roomNumber,player.equals(name),i.a)){if(player.equals(name))notifyNetwork(new Network.Notice("Your partner should check this."));else server.send(new Network.Notice("Your partner should check this."));return;}if(i.type==Network.Intent.Type.DOOR_CONFIRM)i.a=player.equals(name)?"host":"client";IntentHandler.Result r;if(i.type==Network.Intent.Type.USE_HINT)r=applyHint(player);else r=intents.apply(state,i,player);if(!r.accepted()){if(player.equals(name))notifyNetwork(new Network.Notice(r.notice()));else{server.send(new Network.Notice(r.notice()));notifyNetwork(new Network.Notice(player+" submitted an incorrect answer."));}}else if(!r.event().isEmpty()){Network.GameEvent event=new Network.GameEvent(r.event(),player);server.send(event);notifyNetwork(event);String milestone=switch(r.event()){case "CableCrimped"->"solved the cable crimp";case "RouterOnline"->"restored the network";case "WhiteboardSolved"->"solved the whiteboard";case "TerminalSolved"->"solved the terminal";case "CabinetOpened"->"opened the cabinet";case "KeycardTaken"->"found the operator keycard";case "AttackerIdentified"->"identified the attacker";case "AttackerBlocked"->"isolated the attacker";case "RegisterVerified"->"verified the service register";case "TamperedCameraFound"->"found the tampered camera";case "LockdownReleased"->"released the lockdown";default->"";};if(!milestone.isEmpty())relaySystem(player+" "+milestone);}if(result!=null)result.accept(r);publish();}
    private IntentHandler.Result applyHint(String player){if(state.roomNumber==2||state.roomNumber==3){String[] order={"P1","P2","P3","P4","P5","P6"};boolean[] solved={state.keycardTaken,state.logSolved,state.portsSolved,state.cctvSolved,state.lockdownReleased,state.room2Complete||state.room3Complete};for(int k=0;k<order.length;k++)if(!solved[k]){String id="r2_"+order[k];int old=state.hintTiers.getOrDefault(id,state.hintTiers.getOrDefault("r3_"+order[k],0));int tier=Math.min(3,old+1);if(old<3){state.hintTiers.put(id,tier);state.hintTiers.put("r3_"+order[k],tier);state.room2Hints++;state.room3Hints++;state.room2Score=Math.max(0,state.room2Score-50);state.room3Score=state.room2Score;state.room2SecondsLeft=Math.max(0,state.room2SecondsLeft-60);state.room3SecondsLeft=state.room2SecondsLeft;hintHistory.record(sessionId,id,tier);}Network.GameEvent event=new Network.GameEvent("Hint",order[k]+"|"+tier+"|"+com.networkzero.puzzles.Room2Config.hint(order[k],tier));server.send(event);notifyNetwork(event);return IntentHandler.Result.ok();}return IntentHandler.Result.reject("No hints remaining.");}String[] order={"P1","P2","P3","P4","P6","P7","P8"};for(String id:order){boolean solved=switch(id){case "P1"->state.solved.contains("P3")||state.inventory.contains("Patch Cable");case "P2"->state.logbookRead;case "P3"->state.solved.contains("P3");case "P4"->state.routerOnline;case "P6"->state.boardSolved;case "P7"->state.pcSolved;case "P8"->state.roomComplete;default->true;};if(solved)continue;int old=state.hintTiers.getOrDefault(id,0);if(old>=3)continue;int tier=old+1;state.hintTiers.put(id,tier);state.hintsUsed++;state.score=Math.max(0,state.score-50);state.secondsLeft=Math.max(0,state.secondsLeft-60);hintHistory.record(sessionId,id,tier);String text;try{text=hints.get(id,tier);}catch(Exception e){text="Hint data unavailable.";}state.roomMessage="Hint: "+text;Network.GameEvent event=new Network.GameEvent("Hint",id+"|"+tier+"|"+text);server.send(event);notifyNetwork(event);return IntentHandler.Result.ok();}return IntentHandler.Result.reject("No hints remaining.");}
    private void acceptChat(String player,String text){String clean=ChatFilter.sanitize(text);if(clean.isEmpty())return;long now=System.currentTimeMillis();ArrayDeque<Long> q=chatRates.computeIfAbsent(player,k->new ArrayDeque<>());while(!q.isEmpty()&&now-q.peekFirst()>3000)q.removeFirst();if(q.size()>=5){server.send(new Network.Notice("Chat rate limit: wait a moment."));return;}q.addLast(now);Network.ChatMessage m=new Network.ChatMessage(player,clean,now,false);notifyNetwork(m);server.send(m);}
    private void relaySystem(String text){Network.ChatMessage m=new Network.ChatMessage("SYSTEM",text,System.currentTimeMillis(),true);notifyNetwork(m);server.send(m);}
    public GameState state(){return state;}public void beginRoom2(){state.beginRoom2();publish();}public void beginRoom3(){beginRoom2();}public void submit(Network.Intent i){apply(i,name);}public boolean isRemote(){return false;}public boolean isHost(){return true;}public String localName(){return name;}public String partnerName(){return partner;}public boolean partnerConnected(){return server.connected();}public String partnerActivity(){return activity;}public long pingMs(){return server.pingMs();}public void publish(){server.sync();}public void tick(float dt){lastTimerSync+=dt;if(lastTimerSync>=1){lastTimerSync=0;publish();}}public void sendChat(Network.Chat m){acceptChat(name,m.text);}public void sendPresence(String a){activity=a;server.send(new Network.PresenceUpdate(a));}public void send(Object m){server.send(m);}public void systemLine(String text){relaySystem(text);}public void setNetworkListener(Consumer<Object> c){networkListener=c;}public void setIntentOverride(Consumer<Network.Intent> c){intentOverride=c;}public boolean clientReady(){return clientReady;}public long messageCount(){return server.messageCount();}public void simulateDisconnect(){server.closePeer();}public void stop(){server.close();hintHistory.close();}
    public void close(){stop();}
}
